package io.knowledgebrain.activity;
import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_ACTIVITY_DATABASE_URL",matches=".+")
class ActivityStoreIntegrationTest extends ActivityFixtures {
 PGSimpleDataSource ds;JdbcTemplate sql;ActivityStore store;String schema;
 @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_ACTIVITY_DATABASE_URL"));ds.setUser("brain_activity");ds.setPassword(System.getenv("BRAIN_TEST_ACTIVITY_DATABASE_PASSWORD"));schema="activity_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new ActivityStore(ds);}
 @AfterEach void cleanup(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 @Test void durableDedupRejectsChangedBytesAndSourceVersionCollisions()throws Exception{var wire=wire("ROADMAP",id());var topic=ActivityEvent.TOPICS.get("ROADMAP");store.stage(topic,wire);store.stage(topic,wire);assertEquals(1,store.pendingCount());var original=io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1.parseFrom(wire);assertThrows(RuntimeException.class,()->store.stage(topic,original.toBuilder().setTraceId("b".repeat(32)).build().toByteArray()));assertThrows(RuntimeException.class,()->store.stage(topic,original.toBuilder().setEventId(id().toString()).build().toByteArray()));assertEquals(1,store.pendingCount());var row=store.pending(1).getFirst();assertEquals(original.getEventId(),store.decode(row).eventId().toString());store.applied(row.eventId());assertEquals(0,store.pendingCount());store.stage(topic,wire);assertEquals(0,store.pendingCount());}
 @Test void replayKeepsAllHistoricalFactsAndReadinessWaitsForDrain(){for(var k:ActivityEvent.TOPICS.keySet())store.stage(ActivityEvent.TOPICS.get(k),wire(k,id()));assertFalse(store.state().ready());store.seeded();store.finishIfDrained();assertFalse(store.state().ready());store.appliedAll(store.pending(100).stream().map(ActivityStore.Pending::eventId).toList());store.finishIfDrained();assertTrue(store.state().ready());store.startRebuild();assertTrue(store.state().rebuilding());assertFalse(store.state().ready());assertEquals(ActivityEvent.TOPICS.size(),store.pendingCount());store.finishIfDrained();assertTrue(store.state().rebuilding());store.appliedAll(store.pending(100).stream().map(ActivityStore.Pending::eventId).toList());store.finishIfDrained();assertEquals(new ActivityStore.State(true,false,true),store.state());assertEquals(ActivityEvent.TOPICS.size(),sql.queryForObject("SELECT count(*) FROM activity_inbox",Integer.class));}
 @Test void noteDedupUsesFullWireEvenWhenDifferentSuffixesHaveIdenticalExcerpts()throws Exception{var topic=ActivityEvent.TOPICS.get("NOTE");var env=io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1.parseFrom(wire("NOTE",id()));var p=io.knowledgebrain.contracts.content.v1.NoteChangedPayloadV1.parseFrom(env.getPayload());var first=env.toBuilder().setPayload(p.toBuilder().setMarkdown("x".repeat(9000)+"A").build().toByteString()).build().toByteArray();var different=env.toBuilder().setPayload(p.toBuilder().setMarkdown("x".repeat(9000)+"B").build().toByteString()).build().toByteArray();assertEquals(ActivityEvent.decode(topic,first),ActivityEvent.decode(topic,different));store.stage(topic,first);store.stage(topic,first);assertThrows(RuntimeException.class,()->store.stage(topic,different));assertEquals(1,store.pendingCount());}
 @Test void operatorPoolReusesBoundedOwnerConnectionsAndClosesResources()throws Exception{var config=ActivityConfiguration.databaseOptions(System.getenv("BRAIN_TEST_ACTIVITY_DATABASE_URL"),System.getenv("BRAIN_TEST_ACTIVITY_DATABASE_PASSWORD"),null);config.setPoolName("activity-replay-test");assertEquals(3,config.getMaximumPoolSize());assertEquals(1,config.getMinimumIdle());assertEquals(10000,config.getConnectionTimeout());var pool=new com.zaxxer.hikari.HikariDataSource(config);try(pool){var pids=new HashSet<Integer>();var own=new JdbcTemplate(pool);for(int i=0;i<20;i++)pids.add(own.queryForObject("SELECT pg_backend_pid()",Integer.class));assertTrue(pids.size()<=3);assertEquals("brain_activity",own.queryForObject("SELECT current_user",String.class));assertEquals("10s",own.queryForObject("SHOW statement_timeout",String.class));}assertTrue(pool.isClosed());}

 @Test void associationReplayKeepsOutOfOrderEmptyAndRetiredSnapshotsAndRejectsWireConflict()throws Exception{var topic=ActivityEvent.TOPICS.get("NOTE_CONCEPTS");var space=id();var note=id();var p=io.knowledgebrain.contracts.content.concepts.v1.NoteConceptsChangedPayloadV1.newBuilder().setNoteId(note.toString()).setNoteVersion(9).setNoteState("ACTIVE").setRevisionId(id().toString());var base=io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_CONCEPTS",space));for(long v:List.of(3L,1L,2L)){var wire=base.toBuilder().setAggregateId(note.toString()).setEventId(id().toString()).setPayload(p.setConceptVersion(v).setNoteState(v==3?"RETIRED":"ACTIVE").build().toByteString()).build().toByteArray();store.stage(topic,wire);store.stage(topic,wire);var e=ActivityEvent.decode(topic,wire);assertThrows(RuntimeException.class,()->store.stage(topic,base.toBuilder().setAggregateId(note.toString()).setEventId(e.eventId().toString()).setTraceId("b".repeat(32)).setPayload(p.build().toByteString()).build().toByteArray()));}assertEquals(3,store.pendingCount());for(var row:store.pending(100))assertEquals(9,store.decode(row).noteConcepts().noteVersion());store.seeded();store.appliedAll(store.pending(100).stream().map(ActivityStore.Pending::eventId).toList());store.finishIfDrained();store.startRebuild();assertEquals(3,store.pendingCount());}
 @Test void metadataWireConflictsAndOutOfOrderVersionsPreserveExactDecimalStrings()throws Exception{var topic=ActivityEvent.TOPICS.get("NOTE_METADATA");var space=id();var note=id();var base=io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_METADATA",space));var field=io.knowledgebrain.contracts.content.metadata.v1.MetadataPropertyV1.newBuilder().setPropertyId(id().toString()).setName("precise").setValueType("NUMBER").setJsonValue("12345678901234567890.123456789012345678");for(long v:List.of(3L,1L,2L)){var payload=io.knowledgebrain.contracts.content.metadata.v1.NoteMetadataChangedPayloadV1.newBuilder().setNoteId(note.toString()).setRevisionId(id().toString()).setMetadataVersion(v).setNoteVersion(8).setNoteState(v==3?"RETIRED":"ACTIVE").addProperties(field).build();var raw=base.toBuilder().setAggregateId(note.toString()).setEventId(id().toString()).setPayload(payload.toByteString()).build().toByteArray();store.stage(topic,raw);store.stage(topic,raw);assertThrows(RuntimeException.class,()->store.stage(topic,base.toBuilder().setAggregateId(note.toString()).setEventId(ActivityEvent.decode(topic,raw).eventId().toString()).setPayload(payload.toBuilder().setProperties(0,field.setJsonValue("12345678901234567890.123456789012345679")).build().toByteString()).build().toByteArray()));field.setJsonValue("12345678901234567890.123456789012345678");}assertEquals(3,store.pendingCount());for(var row:store.pending(100))assertEquals("12345678901234567890.123456789012345678",store.decode(row).metadata().properties().getFirst().jsonValue());store.startRebuild();assertEquals(3,store.pendingCount());}
 @Test void linkResolutionVersionsReplayOutOfOrderWithSameBodyVersionAndRejectAlteredWire()throws Exception{var topic=ActivityEvent.TOPICS.get("NOTE_LINKS");var space=id();var note=id();var base=io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_LINKS",space));var p=io.knowledgebrain.contracts.content.links.v1.NoteLinksChangedPayloadV1.newBuilder().setSourceNoteId(note.toString()).setNoteVersion(1).setRevisionId(id().toString());for(long v:List.of(3L,1L,2L)){var raw=base.toBuilder().setAggregateId(note.toString()).setEventId(id().toString()).setPayload(p.setLinkVersion(v).setSourceState(v==3?"RETIRED":"ACTIVE").build().toByteString()).build().toByteArray();store.stage(topic,raw);store.stage(topic,raw);assertThrows(RuntimeException.class,()->store.stage(topic,base.toBuilder().setAggregateId(note.toString()).setEventId(ActivityEvent.decode(topic,raw).eventId().toString()).setTraceId("b".repeat(32)).setPayload(p.build().toByteString()).build().toByteArray()));}assertEquals(3,store.pendingCount());for(var row:store.pending(100))assertEquals(1,store.decode(row).noteLinks().noteVersion());store.startRebuild();assertEquals(3,store.pendingCount());}
 @Test void attachmentSnapshotsReplayOutOfOrderAndRejectMetadataWireConflicts()throws Exception{var topic=ActivityEvent.TOPICS.get("NOTE_ATTACHMENTS");var note=id();var base=io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_ATTACHMENTS",id()));var p=io.knowledgebrain.contracts.content.attachments.v1.NoteAttachmentsChangedPayloadV1.newBuilder().setNoteId(note.toString()).setNoteVersion(9).setRevisionId(id().toString());for(long v:List.of(3L,1L,2L)){var raw=base.toBuilder().setAggregateId(note.toString()).setEventId(id().toString()).setPayload(p.setAttachmentVersion(v).setNoteState(v==3?"RETIRED":"ACTIVE").build().toByteString()).build().toByteArray();store.stage(topic,raw);store.stage(topic,raw);assertThrows(RuntimeException.class,()->store.stage(topic,base.toBuilder().setAggregateId(note.toString()).setEventId(ActivityEvent.decode(topic,raw).eventId().toString()).setTraceId("b".repeat(32)).setPayload(p.build().toByteString()).build().toByteArray()));}assertEquals(3,store.pendingCount());for(var row:store.pending(100))assertEquals(9,store.decode(row).noteAttachments().noteVersion());store.startRebuild();assertEquals(3,store.pendingCount());}

 @Test void mixedClaimVersionsDeduplicateOriginalBytesAndReplayOutOfOrderAfterRetirement()throws Exception{var raw=wire("CLAIM",id());for(long v:List.of(3L,1L,2L)){var bytes=ClaimActivityTest.change(raw,v==1?"CONCEPT":"NUMBER",v==1?id().toString():"9007199254740993.123456789012345678",v,v==3);var topic=v==1?"knowledge.claim.v1":"knowledge.claim.v2";if(v==1)bytes=io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1.parseFrom(bytes).toBuilder().setEventVersion(1).build().toByteArray();store.stage(topic,bytes);store.stage(topic,bytes);var changed=io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1.parseFrom(bytes).toBuilder().setTraceId("b".repeat(32)).build().toByteArray();assertThrows(RuntimeException.class,()->store.stage(topic,changed));}assertEquals(3,store.pendingCount());var entries=store.pending(100).stream().map(store::decode).toList();assertEquals(Set.of(1L,2L,3L),new HashSet<>(entries.stream().map(ActivityEvent::sourceVersion).toList()));assertTrue(entries.stream().filter(e->e.sourceVersion()>1).allMatch(e->e.claim().object().value().equals("9007199254740993.123456789012345678")));store.appliedAll(store.pending(100).stream().map(ActivityStore.Pending::eventId).toList());store.startRebuild();assertEquals(3,store.pendingCount());}
}
